export const OPPORTUNITIES: Opportunity[] = ROWS.map(([id, name, org, type, ages, what, perk, url, stage, tags, region]) => ({
  id, name, org, type, ages: ages.split(";") as Age[], what, perk, url, stage: stage.split(";") as Stage[], tags: tags.split(";") as Tag[], region,
}));

export const OPP_TYPES: OppType[] = ["Competition", "Hackathon", "Program", "Fellowship", "Grant", "Scholarship", "Credits", "Accelerator", "Investor"];
export const AGES: Age[] = ["Middle school", "High school", "College", "18+"];
export const REGIONS = Array.from(new Set(OPPORTUNITIES.map((o) => o.region))).sort((a, b) => (a === "Global" ? -1 : b === "Global" ? 1 : a.localeCompare(b)));

/** Keyword hints used to guess which tags fit a startup from its description. */
const TAG_HINTS: Record<Tag, RegExp> = {
  any: /$^/,
  tech: /\b(apps?|software|platform|website|saas|tech|digital|online|tools?|games?)\b/i,
  ai: /\bai\b|a\.i\.|machine learning|\bml\b|\bgpt|\bllm|chatbot|artificial intelligence|\bagents?\b/i,
  social: /communit|non-?profit|charity|\bimpact|underserved|poverty|equity|volunteer|homeless|shelter|donat|food bank/i,
  science: /\bscience|research|\blab\b|biolog|chemis|physics|\bstem\b|\bspace\b|engineer|science fair/i,
  climate: /climate|carbon|sustainab|recycl|\benergy|solar|environment|\bwaste\b|food waste|ocean|leftover|thrift|second-?hand/i,
  health: /health|medic|mental|therapy|fitness|wellness|wellbeing|doctor|patient|disease|nutrition|\bsleep|stress|anxiety|journal|\blead\b|tap water/i,
  edtech: /educat|\blearn|tutor|teach|\bstudy|course|homework|\bexams?\b|\bmath\b|algebra|lesson|public speaking/i,
  fintech: /financ|\bmoney\b|(?<!food )\bbank|budget|invest|paycheck|crypto|saving|credit|fintech/i,
  hardware: /hardware|device|robot|sensor|wearable|3d print|drone|physical product|\biot\b|prototype/i,
  design: /design|\bart\b|\barts\b|fashion|streetwear|clothing|creative|\bmusic|\bvideo|\bfilm|photo|\bgames?\b|pixel|embroider/i,
  business: /business|\bshop|\bstore|\bsells?\b|resell|brand|ecommerce|\bservices?\b|agency|retail|marketplace|preorder|bake|cupcake|depop/i,
  coding: /\bcode\b|coding|developer|programm|open source|github|hackathon/i,
  women: /\bwomen\b|\bgirls?\b|female|\bher\b|\bshe\b/i,
  consumer: /consumer|social media|creator|\bfans?\b|\bteens?\b|dating|\bfood|beauty|travel|\bpets?\b|gamers?|families|parents|cupcake|streetwear|sneaker/i,
};

export function tagsFor(text: string): Tag[] {
  return (Object.keys(TAG_HINTS) as Tag[]).filter((t) => TAG_HINTS[t].test(text));
}


/** Ranks opportunities for one founder: stage fit, niche tags, age fit and type preference. */
export function matchOpportunities(opts: { text: string; stage?: Stage; age?: Age | null; types?: OppType[]; limit?: number }): Opportunity[] {
  const want = tagsFor(opts.text);
  const scored = OPPORTUNITIES.map((o) => {
    if (opts.types && !opts.types.includes(o.type)) return null;
    if (opts.age && !o.ages.includes(opts.age) && !o.ages.includes("Any age")) {
      // 18+ programs are still useful to college founders; younger founders can't apply.
      if (!(opts.age === "College" && o.ages.includes("18+"))) return null;
    }
    let s = 0;
    if (opts.stage && o.stage.includes(opts.stage)) s += 3;
    const hit = o.tags.filter((t) => want.includes(t)).length;
    s += hit * 4 + (o.tags.includes("any") ? 1 : 0);
    if (o.region === "Global") s += 1;
    return { o, s };
  }).filter(Boolean) as { o: Opportunity; s: number }[];
  return scored.sort((a, b) => b.s - a.s).slice(0, opts.limit ?? 12).map((x) => x.o);
}
